begin;
alter table public.arena_alliance_missions add column if not exists mission_kind text;alter table public.arena_alliance_missions add column if not exists reward_currency text not null default'coins';alter table public.arena_alliance_missions add column if not exists reward_amount integer not null default 150;
update public.arena_alliance_missions set mission_kind=case when title ilike'%Fé%'then'faith'when title ilike'%Sabedoria%'then'study'else'service'end,reward_currency=case when title ilike'%Servir%'then'gems'else'coins'end,reward_amount=case when title ilike'%Servir%'then 3 when title ilike'%Sabedoria%'then 200 else 150 end where mission_kind is null;
alter table public.arena_alliance_missions alter column mission_kind set not null;alter table public.arena_alliance_missions add constraint arena_alliance_mission_kind_check check(mission_kind in('faith','study','service'));alter table public.arena_alliance_missions add constraint arena_alliance_mission_reward_check check(reward_currency in('coins','gems')and reward_amount between 1 and 1000);
create table public.arena_alliance_mission_checkins(alliance_id uuid not null references public.arena_alliances(id)on delete cascade,user_id uuid not null references public.profiles(id)on delete cascade,mission_kind text not null check(mission_kind in('faith','study','service')),checkin_day date not null default(current_date),created_at timestamptz not null default now(),primary key(alliance_id,user_id,mission_kind,checkin_day));
create table public.arena_alliance_mission_claims(mission_id uuid not null references public.arena_alliance_missions(id)on delete cascade,user_id uuid not null references public.profiles(id)on delete cascade,claimed_at timestamptz not null default now(),primary key(mission_id,user_id));alter table public.arena_alliance_mission_checkins enable row level security;alter table public.arena_alliance_mission_checkins force row level security;alter table public.arena_alliance_mission_claims enable row level security;alter table public.arena_alliance_mission_claims force row level security;revoke all on public.arena_alliance_mission_checkins,public.arena_alliance_mission_claims from anon,authenticated;
create or replace function public.arena_ensure_alliance_weekly_missions(p_alliance uuid)returns void language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.arena_alliance_missions where alliance_id=p_alliance and ends_at>now())then insert into public.arena_alliance_missions(alliance_id,title,description,target,reward_label,starts_at,ends_at,mission_kind,reward_currency,reward_amount)values(p_alliance,'Jornada de Fé','Faça a prática diária de fé em conjunto',35,'150 moedas',date_trunc('week',now()),date_trunc('week',now())+interval'7 days','faith','coins',150),(p_alliance,'Sabedoria Compartilhada','Complete a prática diária de estudo',35,'200 moedas',date_trunc('week',now()),date_trunc('week',now())+interval'7 days','study','coins',200),(p_alliance,'Servir uns aos outros','Registre atos diários de serviço',25,'3 gemas',date_trunc('week',now()),date_trunc('week',now())+interval'7 days','service','gems',3);end if;end;$$;
create or replace function public.arena_get_alliance_mission_board()returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null then raise exception'alliance required';end if;perform public.arena_ensure_alliance_weekly_missions(v_alliance);return jsonb_build_object('missions',(select jsonb_agg(jsonb_build_object('id',m.id,'kind',m.mission_kind,'title',m.title,'description',m.description,'target',m.target,'progress',least(m.progress,m.target),'reward_currency',m.reward_currency,'reward_amount',m.reward_amount,'ends_at',m.ends_at,'checked_today',exists(select 1 from public.arena_alliance_mission_checkins c where c.alliance_id=v_alliance and c.user_id=v_user and c.mission_kind=m.mission_kind and c.checkin_day=current_date),'claimed',exists(select 1 from public.arena_alliance_mission_claims c where c.mission_id=m.id and c.user_id=v_user))order by m.mission_kind)from public.arena_alliance_missions m where m.alliance_id=v_alliance and m.ends_at>now()),'ranking',(select coalesce(jsonb_agg(to_jsonb(x)order by weekly desc),'[]'::jsonb)from(select c.user_id,coalesce(p.display_name,'Guardião')display_name,count(*)::integer weekly from public.arena_alliance_mission_checkins c left join public.profiles p on p.id=c.user_id where c.alliance_id=v_alliance and c.checkin_day>=date_trunc('week',current_date)::date group by c.user_id,p.display_name order by weekly desc limit 10)x));end;$$;
create or replace function public.arena_checkin_alliance_mission(p_kind text)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_mission uuid;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if v_alliance is null or p_kind not in('faith','study','service')then raise exception'invalid checkin';end if;perform public.arena_ensure_alliance_weekly_missions(v_alliance);select id into v_mission from public.arena_alliance_missions where alliance_id=v_alliance and mission_kind=p_kind and ends_at>now()order by ends_at limit 1;insert into public.arena_alliance_mission_checkins(alliance_id,user_id,mission_kind)values(v_alliance,v_user,p_kind);update public.arena_alliance_missions set progress=least(target,progress+1)where id=v_mission;update public.arena_alliance_members set contribution=contribution+3 where alliance_id=v_alliance and user_id=v_user;update public.arena_alliances set xp=xp+3 where id=v_alliance;return jsonb_build_object('checked',true,'mission_id',v_mission);exception when unique_violation then raise exception'already checked today';end;$$;
create or replace function public.arena_claim_alliance_mission(p_mission_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_mission public.arena_alliance_missions%rowtype;v_wallet public.arena_player_wallets%rowtype;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;select*into v_mission from public.arena_alliance_missions where id=p_mission_id and alliance_id=v_alliance and progress>=target and ends_at>now();if not found then raise exception'mission incomplete';end if;insert into public.arena_alliance_mission_claims values(v_mission.id,v_user,now());insert into public.arena_player_wallets(user_id)values(v_user)on conflict(user_id)do nothing;if v_mission.reward_currency='gems'then update public.arena_player_wallets set gems=gems+v_mission.reward_amount where user_id=v_user returning*into v_wallet;else update public.arena_player_wallets set coins=coins+v_mission.reward_amount where user_id=v_user returning*into v_wallet;end if;insert into public.arena_wallet_transactions(user_id,currency,amount,transaction_type,source,reference_id,idempotency_key)values(v_user,v_mission.reward_currency,v_mission.reward_amount,'earn','alliance-mission',v_mission.id::text,'alliance-mission:'||v_mission.id||':'||v_user);return jsonb_build_object('claimed',true,'currency',v_mission.reward_currency,'amount',v_mission.reward_amount,'coins',v_wallet.coins,'gems',v_wallet.gems);exception when unique_violation then raise exception'already claimed';end;$$;
revoke all on function public.arena_ensure_alliance_weekly_missions(uuid)from public;revoke all on function public.arena_get_alliance_mission_board(),public.arena_checkin_alliance_mission(text),public.arena_claim_alliance_mission(uuid)from public;grant execute on function public.arena_get_alliance_mission_board(),public.arena_checkin_alliance_mission(text),public.arena_claim_alliance_mission(uuid)to authenticated;
commit;
